changeSet.sql:
SET QUOTED_IDENTIFIER ON;
IF EXISTS (SELECT 1 FROM sys.check_constraints WHERE name = N'CK_Notifications_Type')
BEGIN
    ALTER TABLE app.Notifications DROP CONSTRAINT CK_Notifications_Type;
    ALTER TABLE app.Notifications ADD CONSTRAINT CK_Notifications_Type CHECK (Type IN (N'WorkoutReminder', N'MembershipReminder', N'ChallengeReminder', N'AiRecommendation', N'WorkoutCompleted', N'StaffLeaveUpdate'));
END;

rollback.sql:
IF EXISTS (SELECT 1 FROM sys.check_constraints WHERE name = N'CK_Notifications_Type')
BEGIN
    ALTER TABLE app.Notifications DROP CONSTRAINT CK_Notifications_Type;
    ALTER TABLE app.Notifications ADD CONSTRAINT CK_Notifications_Type CHECK (Type IN (N'WorkoutReminder', N'MembershipReminder', N'ChallengeReminder', N'AiRecommendation', N'WorkoutCompleted'));
END;

changeSet.sql:
SET QUOTED_IDENTIFIER ON; DECLARE @Now DATETIME2 = SYSUTCDATETIME();
IF NOT EXISTS (SELECT 1 FROM app.FeatureDefinitions WHERE Code = N'STAFF_LEAVE') BEGIN INSERT INTO app.FeatureDefinitions (Id, Code, Name, Description, Category, IsActive, Scope, ConsumesLicense, CreatedAt, UpdatedAt) VALUES ('a2222222-2222-4222-8222-222222222011', N'STAFF_LEAVE', N'Staff leave', N'Apply for leave and review staff leave requests.', N'Platform', 1, N'Tenant', 0, @Now, @Now); END;
INSERT INTO app.PlanFeatures (Id, PlanId, FeatureCode, [Enabled], CreatedAt, UpdatedAt) SELECT NEWID(), p.Id, N'STAFF_LEAVE', CASE WHEN p.Code IN (N'BUSINESS_FREE', N'BASIC', N'PRO', N'ENTERPRISE') THEN 1 ELSE 0 END, @Now, @Now FROM app.Plans p WHERE NOT EXISTS ( SELECT 1 FROM app.PlanFeatures pf WHERE pf.PlanId = p.Id AND pf.FeatureCode = N'STAFF_LEAVE');
IF NOT EXISTS (SELECT 1 FROM app.Permissions WHERE Code = N'LEAVE_APPLY') BEGIN INSERT INTO app.Permissions (Id, Code, Name, Description, CreatedAt, UpdatedAt) VALUES ('22222222-2222-4222-8222-2222222220b1', N'LEAVE_APPLY', N'Apply leave', N'Submit and cancel own staff leave requests.', @Now, @Now), ('22222222-2222-4222-8222-2222222220b2', N'LEAVE_READ', N'Read staff leave', N'View staff leave calendar and request details.', @Now, @Now), ('22222222-2222-4222-8222-2222222220b3', N'LEAVE_APPROVE', N'Approve staff leave', N'Approve or reject staff leave requests.', @Now, @Now); END;
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r JOIN app.Permissions p ON p.Code = N'LEAVE_APPLY' WHERE r.Name IN (N'SuperAdmin', N'GymOwner', N'GymManager', N'Trainer', N'Receptionist') AND NOT EXISTS (SELECT 1 FROM app.RolePermissions rp WHERE rp.RoleId = r.Id AND rp.PermissionId = p.Id);
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r JOIN app.Permissions p ON p.Code IN (N'LEAVE_READ', N'LEAVE_APPROVE') WHERE r.Name IN (N'SuperAdmin', N'GymOwner', N'GymManager') AND NOT EXISTS (SELECT 1 FROM app.RolePermissions rp WHERE rp.RoleId = r.Id AND rp.PermissionId = p.Id);

rollback.sql:
DELETE rp FROM app.RolePermissions rp
INNER JOIN app.Permissions p ON p.Id = rp.PermissionId
WHERE p.Code IN (N'LEAVE_APPLY', N'LEAVE_READ', N'LEAVE_APPROVE');
DELETE FROM app.Permissions WHERE Code IN (N'LEAVE_APPLY', N'LEAVE_READ', N'LEAVE_APPROVE');
DELETE FROM app.PlanFeatures WHERE FeatureCode = N'STAFF_LEAVE';
DELETE FROM app.FeatureDefinitions WHERE Code = N'STAFF_LEAVE';
